var movieName = document.getElementById("movieName");
var authorDirector = document.getElementById("authorDirector");
var select = document.getElementById("select");
var description = document.getElementById("Description");
var movieImg = document.getElementById("moviImg");
var addBtn = document.getElementById("addbtn");
var updateBtn = document.getElementById("updatebtn");

var movieList = [];
var updateIndex;

if (localStorage.getItem("movies")) {
  movieList = JSON.parse(localStorage.getItem("movies"));
  display(movieList);
}

function save() {
  localStorage.setItem("movies", JSON.stringify(movieList));
}

function addMovie() {
  var file = movieImg.files[0];
  if (file) {
    var reader = new FileReader();
    reader.onload = function () { pushMovie(reader.result); };
    reader.readAsDataURL(file);
  } else {
    pushMovie("");
  }
}

function pushMovie(img) {
  movieList.push({
    name: movieName.value,
    author: authorDirector.value,
    category: select.value,
    description: description.value,
    img: img
  });
  save();
  display(movieList);
  resetForm();
}

function resetForm() {
  movieName.value = "";
  authorDirector.value = "";
  select.selectedIndex = 0;
  description.value = "";
  movieImg.value = "";
}

function display(arr) {
  var cartona = "";
  for (var i = 0; i < arr.length; i++) {
    var idx = movieList.indexOf(arr[i]);
    cartona += `
    <div class="col-md-6 col-lg-4 col-xl-3">
      <div class="movie-card">
        <div class="movie-image">
          <img src="${arr[i].img}" class="w-100" alt="${arr[i].name}">
        </div>
        <div class="movie-content">
          <h3 class="card-title">${arr[i].name}</h3>
          <div class="authorDirector">${arr[i].author}</div>
          <div class="moviecategory">${arr[i].category}</div>
          <p class="card-text">${arr[i].description}</p>
          <div class="card-buttons d-flex gap-2 mt-4">
            <button onclick="fillForm(${idx})" class="btn btn-warning text-white w-50">
              <i class="bi bi-pencil-fill"></i> Update
            </button>
            <button onclick="deleteMovie(${idx})" class="btn btn-danger w-50">
              <i class="bi bi-trash-fill"></i> Delete
            </button>
          </div>
        </div>
      </div>
    </div>`;
  }
  document.getElementById("rowData").innerHTML = cartona;
}

function deleteMovie(index) {
  movieList.splice(index, 1);
  save();
  display(movieList);
}

function searchMovie(input) {
  var term = input.value.toLowerCase();
  var result = [];
  for (var i = 0; i < movieList.length; i++) {
    if (movieList[i].name.toLowerCase().includes(term)) {
      result.push(movieList[i]);
    }
  }
  display(result);
}

function fillForm(index) {
  updateIndex = index;
  movieName.value = movieList[index].name;
  authorDirector.value = movieList[index].author;
  select.value = movieList[index].category;
  description.value = movieList[index].description;
  addBtn.classList.add("d-none");
  updateBtn.classList.remove("d-none");
}

function updateMovie() {
  var m = movieList[updateIndex];
  m.name = movieName.value;
  m.author = authorDirector.value;
  m.category = select.value;
  m.description = description.value;
  save();
  display(movieList);
  resetForm();
  addBtn.classList.remove("d-none");
  updateBtn.classList.add("d-none");
}